import { FormField, TranslatableInput, TranslatableTextarea, type TranslatableValue } from "@godxjp/ui/data-entry";

const [productName, setProductName] = React.useState<TranslatableValue>({ ja: "醤油ラーメン" });
const [description, setDescription] = React.useState<TranslatableValue>({});

<FormField label="商品名" required>
  <TranslatableInput
    locales={["ja", "en", "vi"]}
    fallbackLocale="ja"
    value={productName}
    onValueChange={setProductName}
    errors={{ en: "英語名を入力してください" }}
  />
</FormField>

<FormField label="説明">
  <TranslatableTextarea locales={["ja", "en", "vi"]} value={description} onValueChange={setDescription} rows={3} />
</FormField>
